import { revalidateTag } from 'next/cache'
import { getProducts } from '@/lib/products'

export default async function Page() {
  const products = await getProducts()

  async function syncCatalog() {
    'use server'

    // Kick off the upstream ERP/PIM sync. In practice this enqueues a job that
    // can touch thousands of SKUs, so we don't block the admin on it here.
    // (enqueueCatalogSync() would go here.)

    // Purge the "products" cache tag. `revalidateTag` marks the cache stale and
    // serves the existing value while it's recomputed in the background, so the
    // admin can keep working immediately and any view reading this tag becomes
    // consistent shortly after. We intentionally avoid `updateTag`, which would
    // block this request on freshly recomputed data (read-your-writes).
    revalidateTag('products', 'max')
  }

  return (
    <div>
      <h1>Product Catalog</h1>

      <form action={syncCatalog}>
        <button type="submit">Sync latest catalog</button>
      </form>

      <ul>
        {products.map((product) => (
          <li key={product.id}>
            {product.name} — ${product.price}
          </li>
        ))}
      </ul>
    </div>
  )
}

